#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }
    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> qs[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    sort(edges.begin(), edges.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[2] < y[2]; });
    vector<int> order(q);
    for (int i = 0; i < q; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return qs[x][2] < qs[y][2]; });
    vector<string> answer(q);
    size_t pointer = 0;
    for (int i : order) {
        while (pointer < edges.size() && edges[pointer][2] < qs[i][2]) {
            unite((int)edges[pointer][0], (int)edges[pointer][1]);
            pointer++;
        }
        answer[i] = findRoot((int)qs[i][0]) == findRoot((int)qs[i][1]) ? "yes" : "no";
    }
    for (const string& line : answer) cout << line << "\n";

    return 0;
}

