import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][3];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][3];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int people = (int) n, queries = (int) q;
        parent = new int[people + 1];
        sizes = new int[people + 1];
        for (int v = 0; v <= people; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        Arrays.sort(edges, (x, y) -> Long.compare(x[2], y[2]));
        Integer[] order = new Integer[queries];
        for (int i = 0; i < queries; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> Long.compare(qs[x][2], qs[y][2]));
        String[] answer = new String[queries];
        int pointer = 0;
        for (int i : order) {
            while (pointer < edges.length && edges[pointer][2] < qs[i][2]) {
                unite((int) edges[pointer][0], (int) edges[pointer][1]);
                pointer++;
            }
            answer[i] = findRoot((int) qs[i][0]) == findRoot((int) qs[i][1]) ? "yes" : "no";
        }
        StringBuilder out = new StringBuilder();
        for (String line : answer) out.append(line).append("\n");
        System.out.print(out);
    }
}
